//! Native TITLE RCDATA retains exact DOM units and normalized document title.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<!doctype html><html><head><title id=title>Held</title></head><body><input id=neighbor value=seed><p id=out>Real</p></body></html>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://title-inner.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->String{let source=format!("var failure=null;try{{{s}}}catch(e){{failure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let Value::String(e)=p.runtime.execute("failure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()else{panic!("Expected refusal: {s}")};e}}}
#[test]
fn title_inner_html_exact_rcdata_units_references_and_normalized_document_title(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var title=document.getElementById('title'),old=title.firstChild,raw='\udfff\ud800\r\n&#13;&amp;&NotEqualTilde;&Afr;&#xD800;\0&lt;img id=fake src=missing&gt;&amp;lt;',expected='\udfff\ud800\n\r&\u2242\u0338\ud835\udd04\ufffd\ufffd<img id=fake src=missing>&lt;',normalized='\udfff\ud800 &\u2242\u0338\ud835\udd04\ufffd\ufffd<img id=fake src=missing>&lt;';title.innerHTML=raw;if(title.firstChild===old||old.parentNode!==null||old.data!=='Held'||title.firstChild.data!==expected||title.text!==expected||title.textContent!==expected||title.firstChild.data.charCodeAt(2)!==10||title.firstChild.data.charCodeAt(3)!==13||title.firstChild.ownerDocument!==document||document.title!==normalized||document.title.charCodeAt(0)!==57343||document.title.charCodeAt(1)!==55296||document.getElementById('fake')!==null||document.getElementById('neighbor').value!=='seed')throw 'actual exact RCDATA and normalized native title';
"#);assert!(d.title.starts_with("\u{fffd}\u{fffd} &"));assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn title_inner_html_detached_title_author_conversion_and_scalar_context(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var title=document.getElementById('title'),other=document.createElement('title'),calls=0;other.innerHTML='Detached&amp;&lt;b&gt;';if(other.text!=='Detached&<b>'||other.innerHTML!=='Detached&amp;&lt;b&gt;'||other.ownerDocument!==document||other.isConnected||document.title!=='Held')throw 'detached title leaves actual displayed title';title.innerHTML={toString:function(){calls++;document.getElementById('out').textContent='Converted';return ' \tA\r\n&#13;&amp; \t';}};if(calls!==1||title.text!==' \tA\n\r& \t'||document.title!=='A &'||document.getElementById('out').textContent!=='Converted'||other.text!=='Detached&<b>')throw 'actual scalar title conversion and normalization';
"#);assert_eq!(d.title,"A &");
}
#[test]
fn title_inner_html_native_records_ranges_iterator_exact_clone_clear_and_recovery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var title=document.getElementById('title'),old=title.firstChild,r=document.createRange(),it=document.createNodeIterator(title,4),watch=new MutationObserver(function(){});r.setStart(old,1);r.setEnd(old,3);if(it.nextNode()!==old)throw 'actual title iterator setup';watch.observe(title,{childList:true,characterData:true,subtree:true});title.innerHTML='\udfff\ud800&amp;lt;&lt;b&gt;';var text=title.firstChild,expected='\udfff\ud800&lt;<b>',records=watch.takeRecords(),copy=text.cloneNode(true);if(text.data!==expected||document.title!==expected||text.parentNode!==title||old.parentNode!==null||old.data!=='Held'||r.startContainer!==title||r.startOffset!==0||r.endContainer!==title||r.endOffset!==0||it.nextNode()!==text||copy===text||copy.data!==expected||copy.parentNode!==null||records.length!==1||records[0].target!==title||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==text)throw 'actual title replacement identity and records';title.innerHTML='';records=watch.takeRecords();if(title.firstChild!==null||title.text!==''||document.title!==''||text.parentNode!==null||text.data!==expected||copy.data!==expected||records.length!==1||records[0].removedNodes[0]!==text||records[0].addedNodes.length)throw 'actual native title clearing';title.innerHTML='Fresh&amp;';records=watch.takeRecords();if(title.text!=='Fresh&'||document.title!=='Fresh&'||records.length!==1||records[0].addedNodes[0]!==title.firstChild)throw 'actual title fresh recovery';
"#);assert_eq!(d.title,"Fresh&");
}
#[test]
fn title_inner_html_quota_and_owner_refusals_preserve_native_title_then_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var title=document.getElementById('title'),old=title.firstChild,watch=new MutationObserver(function(){}),foreign=document.createElementNS('http://www.w3.org/2000/svg','title'),owner=document.implementation.createHTMLDocument('other'),inert=owner.createElement('title');watch.observe(title,{childList:true,characterData:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let display=d.title.clone();let commits=p.state.dom_commits;let retained=p.state.retained_limit;let nodes=p.state.node_limit;let strings=p.state.limits.host.string_bytes;
 for source in ["title.innerHTML='New&#13;&amp;';","title.innerHTML='\\udfff\\ud800&#13;&amp;';"]{for mode in 0..6{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),4=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=refusal(&mut d,&mut f,&mut p,source).to_ascii_lowercase();assert!(e.contains("limit")||e.contains("allowance")||e.contains("storage"),"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(d.title,display);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=retained;p.state.node_limit=nodes;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;}}
 for source in ["foreign.innerHTML='\\ud800&amp;';","inert.innerHTML='\\ud800&amp;';"]{p.begin_job();assert!(!refusal(&mut d,&mut f,&mut p,source).is_empty());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(d.title,display);assert_eq!(p.state.dom_commits,commits);}
 p.begin_job();p.state.limits.host.string_bytes=3;let e=refusal(&mut d,&mut f,&mut p,"title.innerHTML='\\0\\0';");assert!(e.contains("Decoded"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(d.title,display);p.state.limits.host.string_bytes=strings;p.begin_job();run(&mut d,&mut f,&mut p,"if(title.firstChild!==old||title.text!=='Held'||document.title!=='Held'||watch.takeRecords().length)throw 'no native title prefix';title.innerHTML='\\udfff\\ud800&amp;';if(title.text!=='\\udfff\\ud800&'||document.title!=='\\udfff\\ud800&'||watch.takeRecords().length!==1)throw 'actual native title quota recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
